from rules import amount


def solve(data):
    balances = dict(data.get('opening', {}))
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data.get('events', [])):
        if event.get('sequence', 0) > cutoff:
            continue
        identity = ('id', event['id']) if 'id' in event else ('anonymous', position)
        revision = event.get('revision', 0)
        previous = winners.get(identity)
        if previous is None or revision >= previous[0]:
            winners[identity] = (revision, position, event)

    for _, _, event in winners.values():
        if event.get('void', False):
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances[key] = balances.get(key, 0) + amount(event, data.get('rounding', 'floor'))

    return {'balances': balances}

def _rounded(numerator, mode):
    if mode == 'half_up':
        return (numerator + 5000) // 10000
    return numerator // 10000


def amount(event, mode):
    price_quantity = event['price'] * event.get('quantity', 1)
    discount = max(0, min(10000, event.get('discount_bp', 0)))
    net = _rounded(price_quantity * (10000 - discount), mode)
    tax = _rounded(net * event.get('tax_bp', 0), mode)
    total = net + tax
    if event.get('kind') == 'refund':
        return -total
    return total
